"""Genera un anotador HTML autocontenido para los clips del candidato RTVA."""
from __future__ import annotations
import csv,json,html
from pathlib import Path
ROOT=Path(__file__).parents[1]
CAND=ROOT/'proveniencia'/'candidats'/'lead-rtva-001'

def main():
 rows=list(csv.DictReader((CAND/'formes-joan-clips.tsv').open(encoding='utf-8'),delimiter='\t'))
 items=[]
 for r in rows:
  items.append({'id':f"{r['forma']}::{r['segment']}",'form':r['forma'],'segment':r['segment'],'clip':r['clip'],'start':r['inici_clip_s'],'end':r['final_clip_s'],'small':r['small'],'base':r['base'],'priority':r['prioritat']})
 payload=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
 title='Audició — candidat RTVA Joan Verdú'
 out=CAND/'auditoria.html'
 doc=f'''<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>body{{font:16px system-ui,sans-serif;max-width:980px;margin:2rem auto;padding:0 1rem;color:#222}}label{{display:block;margin:.7rem 0}}select,input,textarea,button{{font:inherit;padding:.4rem}}textarea{{width:100%;min-height:4rem}}audio{{width:100%;margin:1rem 0}}.meta{{background:#f3f3f3;padding:.8rem;border-radius:.4rem}}.warn{{background:#fff4ce;padding:.6rem;border-radius:.4rem}}.progress{{float:right;color:#666}}</style></head><body><h1>{title} <span class="progress" id="progress"></span></h1><p>10 clips extrets de les formes amb hipòtesi de veu de Joan. Les anotacions es guarden al navegador i es poden descarregar com a TSV.</p><p><button id="prev">Anterior</button> <button id="next">Següent</button> <button id="download">Descarrega TSV</button></p><main id="app"></main><script>const items={payload};const key='maia-candidat-joan-audicio-v1';let notes=JSON.parse(localStorage.getItem(key)||'{{}}'),index=0;const app=document.querySelector('#app');function render(){{const x=items[index];const n=notes[x.id]||{{}};document.querySelector('#progress').textContent=`${{index+1}}/${{items.length}}`;app.innerHTML=`<h2>${{x.form}}</h2><div class="meta"><p><b>Segment:</b> ${{x.segment}} · <b>Clip:</b> <code>${{x.clip}}</code></p><p><b>Finestra:</b> ${{x.start}}–${{x.end}} s · <b>small:</b> ${{x.small}} · <b>base:</b> ${{x.base}} · <b>prioritat:</b> ${{x.priority}}</p></div><audio controls preload="metadata" src="${{x.clip}}"></audio><p class="warn">Escolta abans d'escriure una variant. La forma ASR és una hipòtesi i el segment pot ser de l'entrevistador.</p><label>Veu<select id="speaker"><option>pendent</option><option>joan</option><option>entrevistador</option><option>mixt</option><option>incerta</option></select></label><label>Decisió de la forma<select id="decision"><option>pendent</option><option>sí</option><option>no</option><option>incerta</option></select></label><label>Variant escoltada<input id="variant"></label><label>Trets fonètics<textarea id="phon"></textarea></label><label>Prosòdia / pauses<textarea id="pros"></textarea></label><label>Nota<textarea id="note"></textarea></label>`;for(const [id,k] of [['speaker','speaker'],['decision','decision'],['variant','variant'],['phon','phon'],['pros','pros'],['note','note']]){{const el=document.querySelector('#'+id);el.value=n[k]||'';el.addEventListener('input',()=>save(x))}}}}function save(x){{notes[x.id]={{speaker:document.querySelector('#speaker').value,decision:document.querySelector('#decision').value,variant:document.querySelector('#variant').value,phon:document.querySelector('#phon').value,pros:document.querySelector('#pros').value,note:document.querySelector('#note').value}};localStorage.setItem(key,JSON.stringify(notes))}}document.querySelector('#prev').onclick=()=>{{index=Math.max(0,index-1);render()}};document.querySelector('#next').onclick=()=>{{index=Math.min(items.length-1,index+1);render()}};document.querySelector('#download').onclick=()=>{{const h=['id','forma','segment','clip','speaker','decision','variant','phon','pros','note'];const lines=[h.join('\\t')];for(const x of items){{const n=notes[x.id]||{{}};lines.push([x.id,x.form,x.segment,x.clip,n.speaker||'pendent',n.decision||'pendent',n.variant||'',n.phon||'',n.pros||'',n.note||''].map(v=>String(v).replace(/[\\t\\n]/g,' ')).join('\\t'))}}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\\n')],{{type:'text/tab-separated-values'}}));a.download='anotacions-joan-verdu.tsv';a.click()}};render();</script></body></html>'''
 out.write_text(doc,encoding='utf-8')
 print(f'generat {out} amb {len(items)} clips')
if __name__=='__main__':main()
